CELL = "cell"

# Byte 0 of the cell's PROFINET frame == %I500 / %Q500 (ir340r01's block base).
# Override per run with --address-base for a PLC with a different frame.
ADDRESS_BASE = 500

# Robots left out of a whole-cell sync: they have a bus_io/PLCTags.xml but are
# not on CELL. ir999r01 is the test robot on its own NOVA instance and its own
# PLC (plc-basement/) — same exclusion as build_tag_table.py. Naming one with
# --robot overrides this, so its own cell can still be synced.
EXCLUDED_ROBOTS = {"ir999r01"}

TYPES = {
    'Bool': ProfinetIOTypeEnum.PROFINET_IO_TYPE_BOOL,
    'USInt': ProfinetIOTypeEnum.PROFINET_IO_TYPE_USINT,
    'SInt': ProfinetIOTypeEnum.PROFINET_IO_TYPE_SINT,
    'UInt': ProfinetIOTypeEnum.PROFINET_IO_TYPE_UINT,
    'Int': ProfinetIOTypeEnum.PROFINET_IO_TYPE_INT,
    'UDInt': ProfinetIOTypeEnum.PROFINET_IO_TYPE_UDINT,
    'DInt': ProfinetIOTypeEnum.PROFINET_IO_TYPE_DINT,
    'Real': ProfinetIOTypeEnum.PROFINET_IO_TYPE_REAL,
}

TAG = re.compile(
    r"<Tag\s+type='(?P<type>\w+)'[^>]*?remark='(?P<remark>[^']*)'\s+addr='(?P<addr>[^']+)'>(?P<name>\w+)</Tag>"
)
# %I789.0 / %Q797.2 (bit) | %IB788 / %QB500 | %IW808 | %ID810
ADDR = re.compile(r'^%(?P<area>[IQ])(?P<width>[BWDX]?)(?P<byte>\d+)(?:\.(?P<bit>\d))?$')


def parse_addr(addr: str):
    """-> (area, byte, bit|None). Raises on anything unrecognised."""
    m = ADDR.match(addr)
    if not m:
        raise ValueError(f'unparsable address {addr!r}')
    bit = m.group('bit')
    return m.group('area'), int(m.group('byte')), (int(bit) if bit is not None else None)


def declared(
    root: str, only_robot: str | None = None, address_base: int = ADDRESS_BASE
) -> dict[str, ProfinetIOData]:
    """Desired IO set, gathered from every robot's own bus_io/PLCTags.xml."""
    out: dict[str, ProfinetIOData] = {}
    paths = sorted(glob.glob(os.path.join(root, '*', 'bus_io', 'PLCTags.xml')))
    for path in paths:
        robot = path.split(os.sep)[-3]
        if only_robot and robot != only_robot:
            continue
        if robot in EXCLUDED_ROBOTS and robot != only_robot:
            continue
        # commented-out tags are declarations that were deliberately retired
        live_lines = [ln for ln in open(path, encoding='utf-8') if not ln.strip().startswith('<!--')]
        for m in TAG.finditer('\n'.join(live_lines)):
            name, kind, addr = m.group('name'), m.group('type'), m.group('addr')
            if kind not in TYPES:
                raise SystemExit(f'{robot}: unsupported tag type {kind!r} on {name}')
            area, byte, bit = parse_addr(addr)
            out[name] = ProfinetIOData(
                description=m.group('remark'),
                type=TYPES[kind],
                # NOVA's direction is the mirror of the PLC's: %I (A signal) is
                # written by NOVA, %Q (E signal) is read by NOVA.
                direction=(ProfinetIODirection.PROFINET_IO_DIRECTION_OUTPUT if area == 'I'
                           else ProfinetIODirection.PROFINET_IO_DIRECTION_INPUT),
                byte_address=byte - address_base,
                bit_address=bit,
            )
    return out


def ident(x) -> tuple:
    """Comparable identity. Compare enum *values*: the listing comes back as
    the client ships the same model names under both `v2` and `v2_pydantic`, so
    enum members can be distinct classes with equal values."""
    return (x.type.value, x.direction.value, x.byte_address, x.bit_address)


def same(a, b) -> bool:
    return ident(a) == ident(b)


def overlaps(io, other) -> bool:
    """True if two same-direction IOs share any byte (a word covers 2-4 bytes)."""
    widths = {'PROFINET_IO_TYPE_REAL': 4, 'PROFINET_IO_TYPE_UDINT': 4, 'PROFINET_IO_TYPE_DINT': 4,
              'PROFINET_IO_TYPE_UINT': 2, 'PROFINET_IO_TYPE_INT': 2}

    def span(x):
        n = widths.get(x.type.value, 1)
        return range(x.byte_address, x.byte_address + n)

    return io.direction.value == other.direction.value and bool(set(span(io)) & set(span(other)))

